  on conflict (key) do update set value = excluded.value, updated_at = now();
insert into public.decision_policy (key, value, description) values ('supplier_nonresponse_interest_apr_from_v14', to_jsonb(0.12::numeric), $qd$what fn_accountant_nonresponse_charge charges a supplier who accepted v14 or later before the reveal. Source: src/content/company_facts.json 2026-09-24.2.$qd$)
  on conflict (key) do update set value = excluded.value, updated_at = now();

-- re-render the company knowledge the seats read
do $s$ begin perform public.fn_company_org_directory_sync(); perform public.fn_company_self_knowledge_sync(); end $s$;

-- verdict
select case when (select count(*) = 1 from public.legal_documents where slug = 'customer-terms' and version = 'v9' and content_sha256 = 'bdb2f121231943920fa542dc06bd774e05b8fcd7b76f4b8664f8275f4da065bb')
   and (select count(*) = 1 from public.legal_documents where slug = 'supplier-agreement' and version = 'v14' and content_sha256 = 'aa8d424c0276c8f5df6e9cadce01d7b37089318d00a1737ae9c8ecf5ab26a51a')
   and (select value from public.app_secrets where key = 'customer_terms_version') = 'v9'
   and (select value from public.app_secrets where key = 'terms_version') = 'v14'
  then 'PROBE OK' else 'PROBE FAILED: the registry does not carry the generated bodies and versions' end as verdict;

commit;
